// @FIGURE_CODE_BEGIN
/* ───────── geometry constants (fixed drawing scale) ───────── */
var EW = 720, EH = 524, ECX = 360, ECY = 262, ES = 38;
var C_BLUE = '#1a7fba', C_RED = '#e8231a', C_GREEN = '#3ab54a', C_TXT = '#111';
var C_A = '#d32f2f', C_B = '#d32f2f', C_C = '#2e9e44';
var SERIF = 'Georgia, "Times New Roman", Times, serif';

var ellDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
ellDraw.viewbox(0, 0, EW, EH);
ellDraw.rect(EW, EH).fill('#ffffff');

var gAxis = ellDraw.group(), gDash = ellDraw.group(), gCurve = ellDraw.group(),
    gDots = ellDraw.group(), gLab = ellDraw.group();

var estate = { a: 5, b: 3, param: false };

/* ───────── small helpers ───────── */
function lab(g, s, x, y, anchor, size, italic, color) {
  var t = (typeof g.plain === 'function') ? g.plain(s) : g.text(s);
  t.font({ family: SERIF, size: size || 17, anchor: anchor || 'middle' });
  if (italic) t.font('style', 'italic');
  t.fill(color || C_TXT);
  t.attr({ x: x, y: y });
  var kids = t.children ? t.children() : [];
  for (var i = 0; i < kids.length; i++) { if (kids[i] && kids[i].attr) kids[i].attr({ x: x, dy: 0 }); }
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return t;
}
function arrowHead(g, x, y, dx, dy, size, color) {
  var L = Math.sqrt(dx * dx + dy * dy) || 1; dx /= L; dy /= L;
  var px = -dy, py = dx, w = size * 0.42;
  var p = [[x, y],
           [x - dx * size + px * w, y - dy * size + py * w],
           [x - dx * size - px * w, y - dy * size - py * w]];
  return g.polygon(p.map(function (q) { return q[0] + ',' + q[1]; }).join(' ')).fill(color);
}
function dblArrow(g, x1, y1, x2, y2, color) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.sqrt(dx * dx + dy * dy);
  if (L < 10) return;
  var ux = dx / L, uy = dy / L;
  g.line(x1 + ux * 1, y1 + uy * 1, x2 - ux * 1, y2 - uy * 1).stroke({ color: color, width: 1.5 });
  arrowHead(g, x2, y2, ux, uy, 9, color);
  arrowHead(g, x1, y1, -ux, -uy, 9, color);
}
function interact(el, tipFn, title, bodyFn) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tipFn(), e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function () { showPopup(title, bodyFn()); });
}

/* ───────── static axes ───────── */
gAxis.line(10, ECY, EW - 34, ECY).stroke({ color: '#000', width: 1.6 });
arrowHead(gAxis, EW - 26, ECY, 1, 0, 11, '#000');
arrowHead(gAxis, 8, ECY, -1, 0, 11, '#000');
gAxis.line(ECX, 16, ECX, EH - 16).stroke({ color: '#000', width: 1.6 });
arrowHead(gAxis, ECX, 8, 0, -1, 11, '#000');
arrowHead(gAxis, ECX, EH - 8, 0, 1, 11, '#000');
lab(gAxis, 'x', EW - 15, ECY + 21, 'middle', 18, true);
lab(gAxis, 'y', ECX - 12, 27, 'end', 18, true);

/* ───────── dashed axes + ellipse ───────── */
var dashH = gDash.line(0, 0, 0, 0).stroke({ color: C_RED, width: 2, dasharray: '9,7' });
var dashV = gDash.line(0, 0, 0, 0).stroke({ color: C_RED, width: 2, dasharray: '9,7' });
var hitH = gDash.line(0, 0, 0, 0).stroke({ color: '#000', width: 16, opacity: 0 }).attr('pointer-events', 'stroke');
var hitV = gDash.line(0, 0, 0, 0).stroke({ color: '#000', width: 16, opacity: 0 }).attr('pointer-events', 'stroke');

var ellEl = gCurve.ellipse(10, 10).center(ECX, ECY).fill('none').stroke({ color: C_BLUE, width: 3 });
var hitEll = gCurve.ellipse(10, 10).center(ECX, ECY).fill('none')
  .stroke({ color: '#000', width: 16, opacity: 0 }).attr('pointer-events', 'stroke');

function isHoriz() { return estate.a >= estate.b; }
function cVal() { return Math.sqrt(Math.abs(estate.a * estate.a - estate.b * estate.b)); }

interact(hitEll,
  function () { return 'Ellipse  x²/a² + y²/b² = 1   (a = ' + estate.a.toFixed(1) + ', b = ' + estate.b.toFixed(1) + ')'; },
  'The ellipse',
  function () { return 'Every point on this blue curve satisfies x²/a² + y²/b² = 1. Equivalently, the sum of the distances from any point on the curve to the two foci is constant and equals twice the semi-major axis. Only the two numbers a and b are needed to pin the whole curve down.'; });

interact(hitH,
  function () { return (isHoriz() ? 'Major axis' : 'Minor axis') + ': horizontal, full length 2a = ' + (2 * estate.a).toFixed(1); },
  'Horizontal axis',
  function () { return isHoriz()
    ? 'This is the major (longer) axis, of full length 2a. It runs vertex-to-vertex through the center and it is the axis that carries the two foci.'
    : 'Here b > a, so the horizontal axis is the minor (shorter) axis, of full length 2a. Its endpoints are the co-vertices, the points of the ellipse closest to the center.'; });

interact(hitV,
  function () { return (isHoriz() ? 'Minor axis' : 'Major axis') + ': vertical, full length 2b = ' + (2 * estate.b).toFixed(1); },
  'Vertical axis',
  function () { return isHoriz()
    ? 'This is the minor (shorter) axis, of full length 2b, perpendicular to the major axis at the center. Its endpoints are the co-vertices.'
    : 'Because b > a, the vertical axis is now the major (longer) axis of length 2b; the vertices and the foci have moved onto it.'; });

/* ───────── dots ───────── */
function dot(x, y, r, color, tip, title, body) {
  gDots.circle(2 * r).center(x, y).fill(color);
  var hit = gDots.circle(26).center(x, y).fill('#fff').opacity(0);
  interact(hit, function () { return tip; }, title, function () { return body; });
}

/* ───────── named-feature labels ───────── */
function renderNames(a, b, c, aS, bS, cS, horiz) {
  var hName = horiz ? 'Vertex' : 'Co-vertex';
  var vName = horiz ? 'Co-vertex' : 'Vertex';
  lab(gLab, hName, ECX + aS + 12, ECY - 5, 'start');
  lab(gLab, hName, ECX - aS - 12, ECY - 5, 'end');
  lab(gLab, vName, ECX + 12, ECY - bS + 6, 'start');
  if (bS >= 46) lab(gLab, vName, ECX + 12, ECY + bS + 6, 'start');
  else lab(gLab, vName, ECX - 12, ECY + bS + 18, 'end');
  lab(gLab, 'Center', ECX + 10, ECY + 22, 'start');

  if (aS > 112) lab(gLab, horiz ? 'Major Axis' : 'Minor Axis', ECX - aS / 2, ECY + 22, 'middle');
  if (bS > 80) lab(gLab, horiz ? 'Minor Axis' : 'Major Axis', ECX + 13, ECY - bS / 2 + 6, 'start');

  if (horiz) {
    if (2 * cS >= 110) {
      var fy = (aS - cS < 75) ? ECY + 21 : ECY - 14;
      lab(gLab, 'Focus', ECX + cS, fy, 'middle');
      lab(gLab, 'Focus', ECX - cS, fy, 'middle');
    } else {
      gLab.line(ECX - 32, ECY - 34, ECX - cS, ECY - 7).stroke({ color: '#777', width: 0.9 });
      gLab.line(ECX - 32, ECY - 34, ECX + cS, ECY - 7).stroke({ color: '#777', width: 0.9 });
      lab(gLab, 'Foci', ECX - 34, ECY - 30, 'end');
    }
  } else {
    if (2 * cS >= 46) {
      lab(gLab, 'Focus', ECX - 12, ECY - cS + 6, 'end');
      lab(gLab, 'Focus', ECX - 12, ECY + cS + 6, 'end');
    } else {
      gLab.line(ECX - 32, ECY - 34, ECX - 4, ECY - cS - 4).stroke({ color: '#777', width: 0.9 });
      gLab.line(ECX - 32, ECY - 34, ECX - 4, ECY + cS - 4).stroke({ color: '#777', width: 0.9 });
      lab(gLab, 'Foci', ECX - 34, ECY - 30, 'end');
    }
  }
}

/* ───────── parameter (a, b, c) labels ───────── */
function renderParams(a, b, c, aS, bS, cS, horiz) {
  // a : centre → right end of horizontal semi-axis
  gLab.line(ECX + aS, ECY, ECX + aS, ECY - 26).stroke({ color: '#999', width: 0.9, dasharray: '3,3' });
  dblArrow(gLab, ECX, ECY - 26, ECX + aS, ECY - 26, C_A);
  lab(gLab, 'a', ECX + aS / 2, ECY - 32, 'middle', 19, true, C_A);

  // b : centre → top of vertical semi-axis
  gLab.line(ECX, ECY - bS, ECX - 26, ECY - bS).stroke({ color: '#999', width: 0.9, dasharray: '3,3' });
  dblArrow(gLab, ECX - 26, ECY, ECX - 26, ECY - bS, C_B);
  lab(gLab, 'b', ECX - 34, ECY - bS / 2 + 6, 'end', 19, true, C_B);

  // c : centre → focus, along the major axis
  if (cS > 11) {
    if (horiz) {
      gLab.line(ECX + cS, ECY, ECX + cS, ECY + 26).stroke({ color: '#999', width: 0.9, dasharray: '3,3' });
      dblArrow(gLab, ECX, ECY + 26, ECX + cS, ECY + 26, C_C);
      lab(gLab, 'c', ECX + cS / 2, ECY + 43, 'middle', 19, true, C_C);
    } else {
      gLab.line(ECX, ECY - cS, ECX - 58, ECY - cS).stroke({ color: '#999', width: 0.9, dasharray: '3,3' });
      dblArrow(gLab, ECX - 58, ECY, ECX - 58, ECY - cS, C_C);
      lab(gLab, 'c', ECX - 66, ECY - cS / 2 + 6, 'end', 19, true, C_C);
    }
  }

  lab(gLab, 'x²/a² + y²/b² = 1', 14, 30, 'start', 17, false, '#111');
  lab(gLab, 'c² = a² − b²', 14, 53, 'start', 17, false, '#111');
  lab(gLab, 'a = ' + a.toFixed(1) + '   b = ' + b.toFixed(1) + '   c = ' + c.toFixed(2),
      14, 76, 'start', 15, false, '#444');
}

/* ───────── main render ───────── */
function erender() {
  var a = estate.a, b = estate.b, horiz = a >= b, c = cVal();
  var aS = a * ES, bS = b * ES, cS = c * ES;

  ellEl.size(2 * aS, 2 * bS).center(ECX, ECY);
  hitEll.size(2 * aS, 2 * bS).center(ECX, ECY);
  dashH.plot(ECX - aS, ECY, ECX + aS, ECY);
  hitH.plot(ECX - aS, ECY, ECX + aS, ECY);
  dashV.plot(ECX, ECY - bS, ECX, ECY + bS);
  hitV.plot(ECX, ECY - bS, ECX, ECY + bS);

  gDots.clear(); gLab.clear();

  dot(ECX, ECY, 5, '#000', 'Center (0, 0)', 'Center',
    'The center is the midpoint of both axes and the point of symmetry of the ellipse. Vertices, co-vertices and foci are all measured outward from it, and it never moves as you change a or b.');

  var vTip = horiz ? 'Vertex (±a, 0) — a = ' + a.toFixed(1) : 'Co-vertex (±a, 0) — a = ' + a.toFixed(1);
  var vTitle = horiz ? 'Vertex' : 'Co-vertex';
  var vBody = horiz
    ? 'A vertex is an endpoint of the major (longer) axis, at distance a = ' + a.toFixed(1) + ' from the center. The vertices are the points of the ellipse farthest from the center.'
    : 'Because b > a, the horizontal endpoints are co-vertices: endpoints of the minor axis, at distance a = ' + a.toFixed(1) + ' from the center.';
  dot(ECX + aS, ECY, 5, '#000', vTip, vTitle, vBody);
  dot(ECX - aS, ECY, 5, '#000', vTip, vTitle, vBody);

  var wTip = horiz ? 'Co-vertex (0, ±b) — b = ' + b.toFixed(1) : 'Vertex (0, ±b) — b = ' + b.toFixed(1);
  var wTitle = horiz ? 'Co-vertex' : 'Vertex';
  var wBody = horiz
    ? 'A co-vertex is an endpoint of the minor (shorter) axis, at distance b = ' + b.toFixed(1) + ' from the center. Co-vertices are the points of the ellipse closest to the center.'
    : 'With b > a the vertical endpoints become the vertices: endpoints of the major axis, at distance b = ' + b.toFixed(1) + ' from the center.';
  dot(ECX, ECY - bS, 5, '#000', wTip, wTitle, wBody);
  dot(ECX, ECY + bS, 5, '#000', wTip, wTitle, wBody);

  var fTip = 'Focus — c = √|a² − b²| = ' + c.toFixed(2) + ' from the center';
  var fBody = 'The foci are not free to move: they sit on the major axis at distance c = √(a² − b²) = ' + c.toFixed(2) +
    ' from the center. When b equals a the radicand is zero, both foci land on the center, and the ellipse is a circle.';
  if (horiz) {
    dot(ECX + cS, ECY, 4, C_GREEN, fTip, 'Focus', fBody);
    dot(ECX - cS, ECY, 4, C_GREEN, fTip, 'Focus', fBody);
  } else {
    dot(ECX, ECY - cS, 4, C_GREEN, fTip, 'Focus', fBody);
    dot(ECX, ECY + cS, 4, C_GREEN, fTip, 'Focus', fBody);
  }

  if (estate.param) renderParams(a, b, c, aS, bS, cS, horiz);
  else renderNames(a, b, c, aS, bS, cS, horiz);

  var ro = document.getElementById('ellReadout');
  if (ro) {
    var semiMajor = Math.max(a, b);
    ro.textContent = 'a = ' + a.toFixed(1) + '   b = ' + b.toFixed(1) +
      '   c = ' + c.toFixed(2) + '   e = c/(semi-major) = ' + (c / semiMajor).toFixed(2) +
      '   |   major axis: ' + (horiz ? 'horizontal' : 'vertical') + (Math.abs(a - b) < 1e-9 ? '  (circle)' : '');
  }
}

/* ───────── control handlers ───────── */
function update_semiMajorA(v) { estate.a = +v; erender(); }
function update_semiMinorB(v) { estate.b = +v; erender(); }
function toggle_labelMode(on) { estate.param = !!on; erender(); }

/* ───────── demo steps ───────── */
var ESTEPS = [
  { title: 'The anatomy of an ellipse', narration: 'Start with the classic wide ellipse: the center at the origin, two vertices on the horizontal (major) axis, two co-vertices on the vertical (minor) axis, and two green foci sitting inside the vertices on the major axis.', state: { a: 5, b: 3, param: false } },
  { title: 'Stretch the major axis', narration: 'Drag a larger. Only the vertices move outward — the co-vertices are unchanged — and the foci slide outward too, because the shape becomes more elongated.', state: { a: 6, b: 3, param: false } },
  { title: 'Stretch the minor axis', narration: 'Now raise b. The co-vertices climb while the vertices stay locked in place, and the foci move back toward the center: the ellipse is getting rounder.', state: { a: 6, b: 5.2, param: false } },
  { title: 'When b = a, the foci merge', narration: 'Set b equal to a. The two foci land exactly on the center, the major and minor axes become equal, and the ellipse is a circle — a circle is an ellipse with c = 0.', state: { a: 6, b: 6, param: false } },
  { title: 'Read the same picture as an equation', narration: 'Flip to the parameter view: the named parts become the distances a, b and c. The ellipse is exactly x²/a² + y²/b² = 1, and the focus distance obeys c² = a² − b².', state: { a: 5, b: 3, param: true } },
  { title: 'A near-flat ellipse', narration: 'Shrink b far below a. The foci run almost out to the vertices and c approaches a — high eccentricity means the foci sit near the ends of the long axis.', state: { a: 6, b: 0.9, param: true } }
];
var ellStep = 0;

function setStep(i) {
  ellStep = (i + ESTEPS.length) % ESTEPS.length;
  var s = ESTEPS[ellStep];
  var ia = document.getElementById('semiMajorAInput'), ib = document.getElementById('semiMinorBInput'),
      ic = document.getElementById('labelModeInput');
  if (ia) { ia.value = s.state.a; document.getElementById('semiMajorAVal').value = s.state.a.toFixed(1); }
  if (ib) { ib.value = s.state.b; document.getElementById('semiMinorBVal').value = s.state.b.toFixed(1); }
  if (ic) { ic.checked = s.state.param; }
  estate.a = s.state.a; estate.b = s.state.b; estate.param = s.state.param;
  var t = document.getElementById('stepTitle'), n = document.getElementById('demoNarration'),
      l = document.getElementById('stepLabel');
  if (t) t.textContent = s.title;
  if (n) n.textContent = s.narration;
  if (l) l.textContent = 'Step ' + (ellStep + 1) + ' / ' + ESTEPS.length;
  erender();
}
function nextStep() { setStep(ellStep + 1); }
function prevStep() { setStep(ellStep - 1); }

setStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Every named part of an ellipse — center, vertices, co-vertices, major and minor axes, and foci — is fixed by just two numbers, the semi-major axis a and the semi-minor axis b, with the foci located at distance c = √(a² − b²) from the center along the major axis.
KEY INSIGHT (what students should walk away understanding): The ellipse's entire vocabulary is just two lengths: a sets the vertices, b sets the co-vertices, and the foci are not free — they are forced to sit at c = √(a² − b²) along the major axis, which is why the ellipse rounds into a circle exactly when a = b.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Every named part of an ellipse — center, vertices, co-vertices, major and minor axes, and foci — is fixed by just two numbers, the semi-major axis a and the semi-minor axis b, with the foci located at distance c = √(a² − b²) from the center along the major axis.",
  "figureType": "diagram",
  "elements": [
    "x-axis: horizontal black line through the origin with a rightward arrowhead, labeled 'x' at the right end",
    "y-axis: vertical black line through the origin with arrowheads at top and bottom, labeled 'y' at the top",
    "Blue ellipse outline centered at the origin, wider than tall (horizontal major axis)",
    "Red dashed horizontal segment from left vertex to right vertex lying on the x-axis (major axis)",
    "Red dashed vertical segment from bottom co-vertex to top co-vertex lying on the y-axis (minor axis)",
    "Black dot at the origin labeled 'Center'",
    "Black dots at (±a, 0) where the ellipse meets the x-axis, each labeled 'Vertex'",
    "Black dots at (0, ±b) where the ellipse meets the y-axis, each labeled 'Co-vertex' (above and below)",
    "Two small green dots at (±c, 0) on the major axis, inside the vertices, each labeled 'Focus'",
